Then, we need logic to calculate snake's next move and check if it's ok

```
pub fn get_next_move(&mut self, width: u32) -> (u32, u32) {
        match self.body.last() {
            Some(val) => {
                let (row, col) = self.get_row_col(*val as usize, width);

                match self.direction {
                    Direction::Up => {
                        if row == 0 {
                            self.alive = false;
                            return (row, col);
                        }
                        (row - 1, col)
                    }
                    Direction::Down => {
                        if row >= width - 1 {
                            // Using width since it's a square grid
                            self.alive = false;
                            return (row, col);
                        }
                        (row + 1, col)
                    }
                    Direction::Left => {
                        if col == 0 {
                            self.alive = false;
                            return (row, col);
                        }
                        (row, col - 1)
                    }
                    Direction::Right => {
                        if col >= width - 1 {
                            self.alive = false;
                            return (row, col);
                        }
                        (row, col + 1)
                    }
                }
            }
            None => panic!("snake body is empty"),
        }
    }
```

